create table public.profissionais (
  id uuid primary key default gen_random_uuid(),
  id_origem integer not null unique,
  crm text not null,
  nome text not null,
  sigla text,
  nome_abreviado text,
  cbo text,
  especialidade text,
  cpf text,
  ativo boolean not null default true,
  origem text not null default 'TB_EXPORTA_PROFISSIONAIS',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint profissionais_nome_nao_vazio check (btrim(nome) <> ''),
  constraint profissionais_crm_nao_vazio check (btrim(crm) <> '')
);
comment on table public.profissionais is 'Cadastro de médicos cirurgiões importado do XML TB_EXPORTA_PROFISSIONAIS.';
comment on column public.profissionais.ativo is 'Mapeamento do XML: ATIVO=-1 significa ativo; ATIVO=0 significa inativo.';
comment on column public.profissionais.id_origem is 'ID original do XML; CRM, CPF e SIGLA não são únicos e não são usados como chave.';
create index profissionais_nome_trgm_idx on public.profissionais using gin (nome extensions.gin_trgm_ops);
create index profissionais_crm_trgm_idx on public.profissionais using gin (crm extensions.gin_trgm_ops);
create index profissionais_especialidade_idx on public.profissionais (especialidade);
create index profissionais_ativo_nome_idx on public.profissionais (ativo, nome);
alter table public.cirurgias add column cirurgiao_profissional_id uuid references public.profissionais(id) on delete set null;
alter table public.cirurgias add column auxiliar_profissional_id uuid references public.profissionais(id) on delete set null;
create index cirurgias_cirurgiao_profissional_id_idx on public.cirurgias(cirurgiao_profissional_id);
create index cirurgias_auxiliar_profissional_id_idx on public.cirurgias(auxiliar_profissional_id);
alter table public.profissionais enable row level security;
grant select, insert, update on public.profissionais to authenticated;
create policy profissionais_operacionais_select on public.profissionais for select to authenticated
using ((select private.has_any_role(array['administrador','coordenacao','cadastro']::text[])));
create policy profissionais_operacionais_insert on public.profissionais for insert to authenticated
with check ((select private.has_any_role(array['administrador','coordenacao','cadastro']::text[])));
create policy profissionais_operacionais_update on public.profissionais for update to authenticated
using ((select private.has_any_role(array['administrador','coordenacao','cadastro']::text[])))
with check ((select private.has_any_role(array['administrador','coordenacao','cadastro']::text[])));
